"""
setup_ops_console.py  (kse-sentinel-ops, Sep 29 2026)

Writes the Sentinel Operations console (Phase A) into this project, created
with the standard React + Vite starter:
  vite.config.js, index.html, README.md, src/main.jsx, src/api.js,
  src/App.jsx, src/index.css
and removes the starter's demo files (src/App.css, src/assets/react.svg,
public/vite.svg).

It also:
  - adds .env to .gitignore, so settings and the API key are never committed;
  - creates .env with VITE_API_BASE=http://localhost:8001 and the
    VITE_API_KEY line COPIED from ../kse-sentinel-terminal/.env, so the key is
    never typed or pasted by hand (skipped if .env already exists).

Usage (from the kse-sentinel-ops folder, after npm create vite and npm install):
  python setup_ops_console.py
"""
import sys
from pathlib import Path

FILES = {'vite.config.js': 'import { defineConfig } from "vite";\nimport react from "@vitejs/plugin-react";\n\n// Port 5174, so the console and the Terminal (5173) can run side by side.\nexport default defineConfig({\n  plugins: [react()],\n  server: { port: 5174, strictPort: true },\n});\n', 'index.html': '<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="UTF-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <meta name="robots" content="noindex, nofollow" />\n    <title>Sentinel Operations</title>\n    <link rel="preconnect" href="https://fonts.googleapis.com" />\n    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />\n    <link href="https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500&family=IBM+Plex+Sans:wght@400;500;600;700&display=swap" rel="stylesheet" />\n  </head>\n  <body>\n    <div id="root"></div>\n    <script type="module" src="/src/main.jsx"></script>\n  </body>\n</html>\n', 'src/main.jsx': 'import { StrictMode } from "react";\nimport { createRoot } from "react-dom/client";\nimport "./index.css";\nimport App from "./App.jsx";\n\ncreateRoot(document.getElementById("root")).render(\n  <StrictMode>\n    <App />\n  </StrictMode>\n);\n', 'src/api.js': '/*\n * src/api.js  (kse-sentinel-ops, Sep 29 2026)\n *\n * The console\'s only link to the backend. Every call carries the platform\n * API key and the team member\'s sign-in token. The token lives in\n * sessionStorage: it is forgotten when the tab closes, and never shared with\n * the client Terminal. An expired token is renewed once through the secure\n * refresh cookie; if that fails the session ends and the sign-in screen shows.\n */\nconst API_BASE = import.meta.env.VITE_API_BASE || "http://localhost:8001";\nconst API_KEY = import.meta.env.VITE_API_KEY || "";\nconst TOKEN_KEY = "kse_ops_token";\n\nexport class ApiError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\nexport class SessionEnded extends Error {}\n\nlet token = sessionStorage.getItem(TOKEN_KEY);\nfunction setToken(t) {\n  token = t;\n  if (t) sessionStorage.setItem(TOKEN_KEY, t);\n  else sessionStorage.removeItem(TOKEN_KEY);\n}\nexport const hasSession = () => !!token;\n\n// FastAPI returns either a sentence or a list of field errors.\nfunction describe(detail, status) {\n  if (typeof detail === "string") return detail;\n  if (Array.isArray(detail) && detail.length) {\n    return detail.map((d) => `${(d.loc || []).slice(-1)[0] || "field"}: ${d.msg}`).join("; ");\n  }\n  return `The request failed (${status}).`;\n}\n\nlet refreshing = null;\nfunction refreshOnce() {\n  if (!refreshing) {\n    refreshing = fetch(`${API_BASE}/api/v1/auth/refresh`, {\n      method: "POST",\n      credentials: "include",\n      headers: { "X-API-Key": API_KEY },\n    })\n      .then(async (r) => {\n        if (!r.ok) return false;\n        const body = await r.json().catch(() => ({}));\n        if (!body.access_token) return false;\n        setToken(body.access_token);\n        return true;\n      })\n      .catch(() => false)\n      .finally(() => { refreshing = null; });\n  }\n  return refreshing;\n}\n\nexport async function api(path, { method = "GET", body } = {}) {\n  const send = () =>\n    fetch(`${API_BASE}${path}`, {\n      method,\n      headers: {\n        "X-API-Key": API_KEY,\n        ...(token ? { Authorization: `Bearer ${token}` } : {}),\n        ...(body !== undefined ? { "Content-Type": "application/json" } : {}),\n      },\n      body: body !== undefined ? JSON.stringify(body) : undefined,\n    });\n  let res;\n  try {\n    res = await send();\n  } catch {\n    throw new ApiError(0, "The server could not be reached. Check that the backend is running.");\n  }\n  if (res.status === 401 && token) {\n    if (await refreshOnce()) res = await send();\n    else {\n      setToken(null);\n      throw new SessionEnded("Your session has ended. Sign in again.");\n    }\n  }\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw new ApiError(res.status, describe(data.detail, res.status));\n  return data;\n}\n\nexport async function signIn(email, password) {\n  let res;\n  try {\n    res = await fetch(`${API_BASE}/api/v1/auth/login`, {\n      method: "POST",\n      credentials: "include",\n      headers: { "X-API-Key": API_KEY, "Content-Type": "application/json" },\n      body: JSON.stringify({ email, password }),\n    });\n  } catch {\n    throw new ApiError(0, "The server could not be reached. Check that the backend is running.");\n  }\n  const data = await res.json().catch(() => ({}));\n  if (!res.ok) throw new ApiError(res.status, describe(data.detail, res.status));\n  setToken(data.access_token);\n  try {\n    return await api("/api/v1/ops-console/me");\n  } catch (e) {\n    // A valid client login that is not a team account must not stay signed in here.\n    await signOut();\n    throw e;\n  }\n}\n\nexport async function signOut() {\n  try {\n    await fetch(`${API_BASE}/api/v1/auth/logout`, {\n      method: "POST",\n      credentials: "include",\n      headers: { "X-API-Key": API_KEY },\n    });\n  } catch { /* the local session ends either way */ }\n  setToken(null);\n}\n', 'src/App.jsx': '/*\n * src/App.jsx  (kse-sentinel-ops, Sep 29 2026)\n *\n * Sentinel Operations, Phase A: the MZE Digital team\'s internal console.\n * Spec: KSE_Sentinel_Operations_Console_Spec.md (v3).\n *\n *   Overview    queue counts, trials ending within 7 days, recent actions\n *   Onboarding  queue on the left, the selected record on the right:\n *               details, reviewer checklist, decisions, trial controls, history\n *   Audit       every console action (owner only)\n *\n * Every decision needs a written reason: the button stays disabled until one\n * is given, and irreversible decisions ask for a second confirmation.\n * Times are shown in Pakistan time (PKT).\n */\nimport { useCallback, useEffect, useState } from "react";\nimport { api, hasSession, SessionEnded, signIn, signOut } from "./api.js";\n\n/* ------------------------------------------------------------ vocabulary */\n\nconst STATUS = {\n  PENDING_REVIEW: "Pending review",\n  MORE_INFO_REQUESTED: "Waiting for client information",\n  TRIAL_ACTIVE: "On trial",\n  TRIAL_EXPIRED: "Trial ended",\n  PAID_ACTIVE: "Paid",\n  REJECTED: "Rejected",\n  SUSPENDED: "Suspended",\n};\nconst ACTION = {\n  "signup.more_info_requested": "Asked for more information",\n  "signup.checklist_updated": "Updated the checklist",\n  "signup.details_updated": "Updated the details",\n  "signup.approved": "Approved",\n  "signup.rejected": "Rejected",\n  "trial.extended": "Extended the trial",\n  "trial.restarted": "Restarted the trial",\n  "trial.stopped": "Stopped the trial",\n  "team.password_reset": "Reset a team password",\n};\nconst QUEUES = [\n  { id: "review", label: "To review", statuses: "PENDING_REVIEW,MORE_INFO_REQUESTED" },\n  { id: "trial", label: "On trial", statuses: "TRIAL_ACTIVE" },\n  { id: "ended", label: "Trial ended", statuses: "TRIAL_EXPIRED" },\n  { id: "paid", label: "Paid", statuses: "PAID_ACTIVE" },\n  { id: "rejected", label: "Rejected", statuses: "REJECTED" },\n];\nconst PKT = new Intl.DateTimeFormat("en-GB", {\n  timeZone: "Asia/Karachi", day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit",\n});\nconst PKT_DAY = new Intl.DateTimeFormat("en-GB", { timeZone: "Asia/Karachi", day: "2-digit", month: "short", year: "numeric" });\nconst when = (iso) => (iso ? `${PKT.format(new Date(iso))} PKT` : "");\nconst day = (iso) => (iso ? PKT_DAY.format(new Date(iso)) : "");\nconst pkr = (n) => (n == null ? "" : `PKR ${Number(n).toLocaleString("en-PK")}`);\nconst daysLeft = (iso) => (iso ? Math.ceil((new Date(iso) - Date.now()) / 86400000) : null);\n\n/* ------------------------------------------------------------ shell */\n\nexport default function App() {\n  const [me, setMe] = useState(null);\n  const [checking, setChecking] = useState(hasSession());\n  const [section, setSection] = useState("overview");\n  const [notice, setNotice] = useState(null);\n\n  const ended = useCallback((err) => {\n    if (err instanceof SessionEnded) {\n      setMe(null);\n      setNotice(err.message);\n      return true;\n    }\n    return false;\n  }, []);\n\n  useEffect(() => {\n    if (!hasSession()) return;\n    api("/api/v1/ops-console/me")\n      .then(setMe)\n      .catch((e) => { if (!ended(e)) setMe(null); })\n      .finally(() => setChecking(false));\n  }, [ended]);\n\n  if (checking) return <div className="boot">Checking your session</div>;\n  if (!me) return <SignIn notice={notice} onSignedIn={(m) => { setNotice(null); setMe(m); }} />;\n\n  const nav = [\n    ["overview", "Overview"],\n    ["onboarding", "Onboarding"],\n    ...(me.team_role === "owner" ? [["audit", "Audit trail"]] : []),\n  ];\n  return (\n    <div className="shell">\n      <aside className="rail">\n        <div className="brand">\n          <span className="brand-mark">KSE Sentinel</span>\n          <span className="brand-name">Operations</span>\n        </div>\n        <nav>\n          {nav.map(([id, label]) => (\n            <button key={id} className={section === id ? "on" : ""} onClick={() => setSection(id)}>{label}</button>\n          ))}\n        </nav>\n        <div className="who">\n          <div>{me.email}</div>\n          <div className="role">Team role: {me.team_role}</div>\n          <button className="link" onClick={async () => { await signOut(); setMe(null); }}>Sign out</button>\n        </div>\n      </aside>\n      <main className="work">\n        {section === "overview" && <Overview onEnded={ended} onOpen={() => setSection("onboarding")} />}\n        {section === "onboarding" && <Onboarding onEnded={ended} />}\n        {section === "audit" && <Audit onEnded={ended} />}\n      </main>\n    </div>\n  );\n}\n\nfunction SignIn({ notice, onSignedIn }) {\n  const [email, setEmail] = useState("");\n  const [password, setPassword] = useState("");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState(null);\n  async function submit(e) {\n    e.preventDefault();\n    setBusy(true);\n    setError(null);\n    try {\n      onSignedIn(await signIn(email.trim(), password));\n    } catch (err) {\n      setError(err.status === 403 && /team account/i.test(err.message)\n        ? "This is not a team account. The console is for the MZE Digital team only."\n        : err.message);\n    } finally {\n      setBusy(false);\n    }\n  }\n  return (\n    <div className="signin">\n      <form onSubmit={submit}>\n        <div className="brand dark">\n          <span className="brand-mark">KSE Sentinel</span>\n          <span className="brand-name">Operations</span>\n        </div>\n        <p className="lede">Internal console for the MZE Digital team.</p>\n        {notice && <p className="msg">{notice}</p>}\n        <label>Email<input type="email" autoComplete="username" value={email} onChange={(e) => setEmail(e.target.value)} required /></label>\n        <label>Password<input type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} required /></label>\n        {error && <p className="msg bad" role="alert">{error}</p>}\n        <button className="primary" disabled={busy}>{busy ? "Signing in" : "Sign in"}</button>\n      </form>\n    </div>\n  );\n}\n\n/* ------------------------------------------------------------ overview */\n\nfunction Overview({ onEnded, onOpen }) {\n  const [data, setData] = useState(null);\n  const [error, setError] = useState(null);\n  useEffect(() => {\n    api("/api/v1/ops-console/overview").then(setData).catch((e) => { if (!onEnded(e)) setError(e.message); });\n  }, [onEnded]);\n  if (error) return <p className="msg bad">{error}</p>;\n  if (!data) return <p className="quiet">Loading</p>;\n  return (\n    <section className="overview">\n      <h1>Overview</h1>\n      <div className="figures">\n        <button className="figure" onClick={onOpen}>\n          <span className="n">{data.awaiting_review}</span>\n          <span className="l">awaiting review</span>\n        </button>\n        <button className="figure" onClick={onOpen}>\n          <span className="n">{data.awaiting_client_information}</span>\n          <span className="l">waiting for client information</span>\n        </button>\n        <div className="figure">\n          <span className="n">{data.counts_by_status.TRIAL_ACTIVE || 0}</span>\n          <span className="l">on trial</span>\n        </div>\n        <div className="figure">\n          <span className="n">{data.counts_by_status.PAID_ACTIVE || 0}</span>\n          <span className="l">paid clients</span>\n        </div>\n      </div>\n\n      <h2>Trials ending within 7 days</h2>\n      {data.trials_ending_within_7_days.length === 0\n        ? <p className="quiet">No trial ends in the next 7 days.</p>\n        : (\n          <table className="plain">\n            <tbody>\n              {data.trials_ending_within_7_days.map((t) => (\n                <tr key={t.tenant_id}>\n                  <td>{t.company_name}</td>\n                  <td>{t.pilot_type === "PAID_PILOT" ? "Paid pilot" : "Free trial"}</td>\n                  <td className="fig">{day(t.trial_expires_at)}</td>\n                  <td className="fig">{daysLeft(t.trial_expires_at)} days left</td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        )}\n\n      <h2>Recent actions</h2>\n      {data.recent_actions.length === 0\n        ? <p className="quiet">No actions recorded yet.</p>\n        : <Timeline items={data.recent_actions.map((a) => ({ ...a, label: `${ACTION[a.action] || a.action}, ${a.target}` }))} />}\n    </section>\n  );\n}\n\n/* ------------------------------------------------------------ onboarding */\n\nfunction Onboarding({ onEnded }) {\n  const [queue, setQueue] = useState(QUEUES[0]);\n  const [list, setList] = useState(null);\n  const [selected, setSelected] = useState(null);\n  const [error, setError] = useState(null);\n\n  const load = useCallback(() => {\n    setError(null);\n    api(`/api/v1/ops-console/signups?status=${queue.statuses}`)\n      .then((d) => setList(d.signups))\n      .catch((e) => { if (!onEnded(e)) setError(e.message); });\n  }, [queue, onEnded]);\n  useEffect(() => { setList(null); setSelected(null); load(); }, [load]);\n\n  return (\n    <section className="onboarding">\n      <div className="queue">\n        <h1>Onboarding</h1>\n        <div className="tabs" role="tablist">\n          {QUEUES.map((q) => (\n            <button key={q.id} role="tab" aria-selected={q.id === queue.id} className={q.id === queue.id ? "on" : ""} onClick={() => setQueue(q)}>{q.label}</button>\n          ))}\n        </div>\n        {error && <p className="msg bad">{error}</p>}\n        {list === null && !error && <p className="quiet">Loading</p>}\n        {list && list.length === 0 && <p className="quiet">Nothing here.</p>}\n        <ul className="rows">\n          {(list || []).map((s) => (\n            <li key={s.tenant_id}>\n              <button className={selected === s.tenant_id ? "on" : ""} onClick={() => setSelected(s.tenant_id)}>\n                <span className="co">{s.company_name}</span>\n                <span className="sub">{[s.city, s.sector].filter(Boolean).join(", ") || s.admin_email}</span>\n                <span className="sub">\n                  {STATUS[s.status] || s.status}\n                  {s.status === "TRIAL_ACTIVE" && s.trial_expires_at ? `, ends ${day(s.trial_expires_at)}` : ""}\n                  {["PENDING_REVIEW", "MORE_INFO_REQUESTED"].includes(s.status) ? `, checklist ${s.checklist_answered} of ${s.checklist_total}` : ""}\n                </span>\n              </button>\n            </li>\n          ))}\n        </ul>\n      </div>\n      <div className="record">\n        {selected\n          ? <Record key={selected} tenantId={selected} onEnded={onEnded} onChanged={load} />\n          : <p className="quiet empty">Select a record from the list.</p>}\n      </div>\n    </section>\n  );\n}\n\nfunction Record({ tenantId, onEnded, onChanged }) {\n  const [rec, setRec] = useState(null);\n  const [error, setError] = useState(null);\n  const load = useCallback(() => {\n    api(`/api/v1/ops-console/signups/${tenantId}`).then(setRec).catch((e) => { if (!onEnded(e)) setError(e.message); });\n  }, [tenantId, onEnded]);\n  useEffect(load, [load]);\n  const changed = () => { load(); onChanged(); };\n\n  if (error) return <p className="msg bad">{error}</p>;\n  if (!rec) return <p className="quiet">Loading</p>;\n  const reviewable = ["PENDING_REVIEW", "MORE_INFO_REQUESTED"].includes(rec.status);\n  const d = rec.details;\n  return (\n    <article>\n      <header className="rec-head">\n        <h2>{rec.company_name}</h2>\n        <span className={`status s-${rec.status}`}>{STATUS[rec.status] || rec.status}</span>\n      </header>\n      {rec.status_note && ["MORE_INFO_REQUESTED", "REJECTED", "TRIAL_EXPIRED", "SUSPENDED"].includes(rec.status) && (\n        <p className="note">{rec.status === "MORE_INFO_REQUESTED" ? "Asked the client: " : "Reason: "}{rec.status_note}</p>\n      )}\n\n      <dl className="facts">\n        <Fact k="Registration number" v={d.registration_number} />\n        <Fact k="Sector" v={d.sector} />\n        <Fact k="City" v={d.city} />\n        <Fact k="Address" v={d.address} />\n        <Fact k="Contact" v={[d.contact_name, d.contact_phone].filter(Boolean).join(", ")} />\n        <Fact k="Website" v={d.website} />\n        <Fact k="Sign-in email" v={rec.admin_email} />\n        <Fact k="Email domain" v={rec.email_domain} />\n        <Fact k="Plan requested" v={[rec.tier, d.seats_requested ? `${d.seats_requested} seats` : null].filter(Boolean).join(", ")} />\n        <Fact k="Signed up" v={when(rec.created_at)} fig />\n        <Fact k="Signup network address" v={rec.signup_ip} fig />\n        {rec.trial_expires_at && (\n          <Fact k={rec.pilot_type === "PAID_PILOT" ? "Paid pilot" : "Free trial"}\n                v={`${day(rec.trial_started_at)} to ${day(rec.trial_expires_at)}${rec.pilot_fee_pkr ? `, ${pkr(rec.pilot_fee_pkr)}` : ""}`} fig />\n        )}\n        {rec.seat_count ? <Fact k="Seats allowed" v={rec.seat_count} fig /> : null}\n      </dl>\n\n      <Checklist rec={rec} onEnded={onEnded} onSaved={changed} />\n      {reviewable && <DetailsEditor rec={rec} onEnded={onEnded} onSaved={changed} />}\n      <Decisions rec={rec} onEnded={onEnded} onDone={changed} />\n\n      <h3>History</h3>\n      {rec.history.length === 0\n        ? <p className="quiet">No actions yet.</p>\n        : <Timeline items={rec.history.map((h) => ({\n            ...h,\n            label: ACTION[h.action] || h.action,\n            change: h.before?.status !== h.after?.status && h.after?.status\n              ? `${STATUS[h.before?.status] || h.before?.status} to ${STATUS[h.after.status] || h.after.status}` : null,\n          }))} />}\n\n      {rec.users.length > 0 && (\n        <>\n          <h3>Users</h3>\n          <table className="plain">\n            <tbody>\n              {rec.users.map((u) => (\n                <tr key={u.user_id}>\n                  <td>{u.email}</td>\n                  <td>{u.role}</td>\n                  <td>{u.email_verified ? "Email verified" : "Email not verified"}</td>\n                  <td className="fig">{u.last_login_at ? `Last sign-in ${when(u.last_login_at)}` : "Never signed in"}</td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </>\n      )}\n    </article>\n  );\n}\n\nconst Fact = ({ k, v, fig }) => (\n  <div className="fact">\n    <dt>{k}</dt>\n    <dd className={fig ? "fig" : ""}>{v || <span className="quiet">Not provided</span>}</dd>\n  </div>\n);\n\n/* ------------------------------------------------------------ checklist and details */\n\nfunction Checklist({ rec, onEnded, onSaved }) {\n  const initial = Object.fromEntries(rec.checklist.map((c) => [c.key, { answer: c.answer || "", note: c.note || "" }]));\n  const [items, setItems] = useState(initial);\n  const [reason, setReason] = useState("");\n  const [state, setState] = useState(null);\n  const dirty = JSON.stringify(items) !== JSON.stringify(initial);\n  async function save() {\n    setState({ busy: true });\n    try {\n      await api(`/api/v1/ops-console/signups/${rec.tenant_id}/checklist`, {\n        method: "PUT",\n        body: { reason, items: Object.fromEntries(Object.entries(items).map(([k, v]) => [k, { answer: v.answer || null, note: v.note || null }])) },\n      });\n      setReason("");\n      setState({ ok: "Checklist saved." });\n      onSaved();\n    } catch (e) {\n      if (!onEnded(e)) setState({ bad: e.message });\n    }\n  }\n  return (\n    <section className="block">\n      <h3>Reviewer checklist</h3>\n      <div className="checks">\n        {rec.checklist.map((c) => (\n          <div className="check" key={c.key}>\n            <span className="q">{c.label}</span>\n            <div className="answers" role="radiogroup" aria-label={c.label}>\n              {[["yes", "Yes"], ["no", "No"], ["n/a", "Not applicable"]].map(([v, l]) => (\n                <button key={v} role="radio" aria-checked={items[c.key].answer === v}\n                        className={`${items[c.key].answer === v ? "on" : ""} a-${v.replace("/", "")}`}\n                        onClick={() => setItems({ ...items, [c.key]: { ...items[c.key], answer: items[c.key].answer === v ? "" : v } })}>{l}</button>\n              ))}\n            </div>\n            <input className="note-in" placeholder="Note (optional)" aria-label={`Note: ${c.label}`} value={items[c.key].note}\n                   onChange={(e) => setItems({ ...items, [c.key]: { ...items[c.key], note: e.target.value } })} />\n            {c.by && <span className="by">Last set by {c.by}, {when(c.at)}</span>}\n          </div>\n        ))}\n      </div>\n      {dirty && (\n        <Reasoned reason={reason} setReason={setReason} label="Save checklist" busy={state?.busy}\n                  placeholder="What did you check, and where?" onSubmit={save} />\n      )}\n      {state?.ok && <p className="msg good">{state.ok}</p>}\n      {state?.bad && <p className="msg bad">{state.bad}</p>}\n    </section>\n  );\n}\n\nconst DETAIL_FIELDS = [\n  ["registration_number", "Registration number"], ["sector", "Sector"], ["city", "City"], ["address", "Address"],\n  ["contact_name", "Contact name"], ["contact_phone", "Contact phone"], ["website", "Website"],\n];\n\nfunction DetailsEditor({ rec, onEnded, onSaved }) {\n  const [open, setOpen] = useState(false);\n  const [form, setForm] = useState(() => Object.fromEntries(DETAIL_FIELDS.map(([k]) => [k, rec.details[k] || ""])));\n  const [reason, setReason] = useState("");\n  const [state, setState] = useState(null);\n  if (!open) return <button className="quietbtn" onClick={() => setOpen(true)}>Edit details</button>;\n  async function save() {\n    setState({ busy: true });\n    const changed = Object.fromEntries(Object.entries(form).filter(([k, v]) => v !== (rec.details[k] || "")));\n    try {\n      await api(`/api/v1/ops-console/signups/${rec.tenant_id}/details`, { method: "PUT", body: { reason, ...changed } });\n      setOpen(false);\n      onSaved();\n    } catch (e) {\n      if (!onEnded(e)) setState({ bad: e.message });\n    }\n  }\n  return (\n    <section className="block">\n      <h3>Edit details</h3>\n      <div className="form-grid">\n        {DETAIL_FIELDS.map(([k, l]) => (\n          <label key={k}>{l}<input value={form[k]} onChange={(e) => setForm({ ...form, [k]: e.target.value })} /></label>\n        ))}\n      </div>\n      <Reasoned reason={reason} setReason={setReason} label="Save details" busy={state?.busy}\n                placeholder="Where did the new details come from?" onSubmit={save} onCancel={() => setOpen(false)} />\n      {state?.bad && <p className="msg bad">{state.bad}</p>}\n    </section>\n  );\n}\n\n/* ------------------------------------------------------------ decisions and trial controls */\n\nfunction Decisions({ rec, onEnded, onDone }) {\n  const [mode, setMode] = useState(null);\n  const reviewable = ["PENDING_REVIEW", "MORE_INFO_REQUESTED"].includes(rec.status);\n  const options = reviewable\n    ? [["approve", "Approve"], ["info", "Ask for more information"], ["reject", "Reject"]]\n    : rec.status === "TRIAL_ACTIVE" ? [["extend", "Extend the trial"], ["stop", "Stop the trial"]]\n      : rec.status === "TRIAL_EXPIRED" ? [["restart", "Restart the trial"]] : [];\n  if (options.length === 0) return null;\n  const close = () => setMode(null);\n  const done = () => { setMode(null); onDone(); };\n  return (\n    <section className="block decide">\n      <h3>{reviewable ? "Decision" : "Trial"}</h3>\n      {!mode && (\n        <div className="choices">\n          {options.map(([id, label]) => (\n            <button key={id} className={id === "reject" || id === "stop" ? "danger-outline" : "outline"} onClick={() => setMode(id)}>{label}</button>\n          ))}\n        </div>\n      )}\n      {mode === "approve" && <Approve rec={rec} onEnded={onEnded} onDone={done} onCancel={close} />}\n      {mode === "info" && (\n        <Simple rec={rec} path="request-info" label="Send request" onEnded={onEnded} onDone={done} onCancel={close}\n                placeholder="What do you need from the client? They will receive this message." />\n      )}\n      {mode === "reject" && (\n        <Simple rec={rec} path="reject" label="Reject" confirmText="Reject this signup? This cannot be undone." danger\n                onEnded={onEnded} onDone={done} onCancel={close} placeholder="Why is this signup rejected?" />\n      )}\n      {(mode === "extend" || mode === "restart") && (\n        <Extend rec={rec} restart={mode === "restart"} onEnded={onEnded} onDone={done} onCancel={close} />\n      )}\n      {mode === "stop" && (\n        <Simple rec={rec} path="trial/stop" base="clients" label="Stop the trial" danger\n                confirmText="Stop this trial now? The client is signed out and cannot sign in again until the trial is restarted."\n                onEnded={onEnded} onDone={done} onCancel={close} placeholder="Why is the trial being stopped?" />\n      )}\n    </section>\n  );\n}\n\nfunction useSubmit(onEnded, onDone) {\n  const [state, setState] = useState(null);\n  const run = async (path, body) => {\n    setState({ busy: true });\n    try {\n      await api(path, { method: "POST", body });\n      onDone();\n    } catch (e) {\n      if (!onEnded(e)) setState({ bad: e.message });\n    }\n  };\n  return [state, run];\n}\n\nfunction Simple({ rec, path, base = "signups", label, placeholder, confirmText, danger, onEnded, onDone, onCancel }) {\n  const [reason, setReason] = useState("");\n  const [state, run] = useSubmit(onEnded, onDone);\n  return (\n    <>\n      <Reasoned reason={reason} setReason={setReason} label={label} placeholder={placeholder} danger={danger}\n                confirmText={confirmText} busy={state?.busy} onCancel={onCancel}\n                onSubmit={() => run(`/api/v1/ops-console/${base}/${rec.tenant_id}/${path}`, { reason })} />\n      {state?.bad && <p className="msg bad">{state.bad}</p>}\n    </>\n  );\n}\n\nfunction Approve({ rec, onEnded, onDone, onCancel }) {\n  const [pilot, setPilot] = useState("FREE_TRIAL");\n  const [days, setDays] = useState(30);\n  const [fee, setFee] = useState("");\n  const [seats, setSeats] = useState(rec.details.seats_requested || 1);\n  const [tier, setTier] = useState(rec.tier || "Tier-2");\n  const [reason, setReason] = useState("");\n  const [state, run] = useSubmit(onEnded, onDone);\n  const ends = new Date(Date.now() + Number(days || 0) * 86400000).toISOString();\n  const valid = days >= 1 && days <= 180 && seats >= 1 && seats <= 500 && (pilot === "FREE_TRIAL" || Number(fee) > 0);\n  return (\n    <>\n      <div className="form-grid">\n        <fieldset className="pilot">\n          <legend>Type</legend>\n          <label><input type="radio" name="pilot" checked={pilot === "FREE_TRIAL"} onChange={() => setPilot("FREE_TRIAL")} /> Free trial</label>\n          <label><input type="radio" name="pilot" checked={pilot === "PAID_PILOT"} onChange={() => setPilot("PAID_PILOT")} /> Paid pilot</label>\n        </fieldset>\n        <label>Length in days (1 to 180)\n          <input type="number" min="1" max="180" value={days} onChange={(e) => setDays(Number(e.target.value))} />\n          <span className="hint">Ends {day(ends)}</span>\n        </label>\n        {pilot === "PAID_PILOT" && (\n          <label>Pilot fee in PKR<input type="number" min="1" value={fee} onChange={(e) => setFee(e.target.value)} /></label>\n        )}\n        <label>Seats (1 to 500)<input type="number" min="1" max="500" value={seats} onChange={(e) => setSeats(Number(e.target.value))} /></label>\n        <label>Tier\n          <select value={tier} onChange={(e) => setTier(e.target.value)}>\n            <option>Tier-1</option><option>Tier-2</option>\n          </select>\n        </label>\n      </div>\n      <Reasoned reason={reason} setReason={setReason} label={pilot === "PAID_PILOT" ? "Approve as paid pilot" : "Approve as free trial"}\n                disabled={!valid} busy={state?.busy} onCancel={onCancel} placeholder="Why is this signup approved?"\n                onSubmit={() => run(`/api/v1/ops-console/signups/${rec.tenant_id}/approve`, {\n                  reason, seat_count: seats, trial_days: days, pilot_type: pilot, tier,\n                  pilot_fee_pkr: pilot === "PAID_PILOT" ? Number(fee) : null,\n                })} />\n      {state?.bad && <p className="msg bad">{state.bad}</p>}\n    </>\n  );\n}\n\nfunction Extend({ rec, restart, onEnded, onDone, onCancel }) {\n  const [days, setDays] = useState(14);\n  const [reason, setReason] = useState("");\n  const [state, run] = useSubmit(onEnded, onDone);\n  const from = restart || !rec.trial_expires_at ? Date.now() : new Date(rec.trial_expires_at).getTime();\n  return (\n    <>\n      <label className="inline">{restart ? "Restart for" : "Add"}\n        <input type="number" min="1" max="180" value={days} onChange={(e) => setDays(Number(e.target.value))} /> days\n        <span className="hint">New end date {day(new Date(from + days * 86400000).toISOString())}</span>\n      </label>\n      <Reasoned reason={reason} setReason={setReason} label={restart ? "Restart the trial" : "Extend the trial"}\n                disabled={!(days >= 1 && days <= 180)} busy={state?.busy} onCancel={onCancel}\n                placeholder="Why is the trial being extended?"\n                onSubmit={() => run(`/api/v1/ops-console/clients/${rec.tenant_id}/trial/extend`, { reason, days })} />\n      {state?.bad && <p className="msg bad">{state.bad}</p>}\n    </>\n  );\n}\n\n/* The console\'s rule made visible: no action without a written reason,\n   and a second, explicit confirmation for anything irreversible. */\nfunction Reasoned({ reason, setReason, label, placeholder, onSubmit, onCancel, busy, disabled, danger, confirmText }) {\n  const [confirming, setConfirming] = useState(false);\n  const ok = reason.trim().length >= 5;\n  return (\n    <div className={`reasoned ${danger ? "danger" : ""}`}>\n      <label>Reason, recorded in the audit trail\n        <textarea rows="2" value={reason} placeholder={placeholder} onChange={(e) => { setReason(e.target.value); setConfirming(false); }} />\n      </label>\n      {!ok && reason.length > 0 && <span className="hint">At least 5 characters.</span>}\n      {confirming && <p className="confirm">{confirmText}</p>}\n      <div className="row">\n        <button className={danger ? "danger" : "primary"} disabled={!ok || busy || disabled}\n                onClick={() => (confirmText && !confirming ? setConfirming(true) : onSubmit())}>\n          {busy ? "Saving" : confirming ? `Yes, ${label.toLowerCase()}` : label}\n        </button>\n        {onCancel && <button className="link" onClick={onCancel}>Cancel</button>}\n      </div>\n    </div>\n  );\n}\n\n/* ------------------------------------------------------------ history and audit */\n\nfunction Timeline({ items }) {\n  return (\n    <ol className="timeline">\n      {items.map((it, i) => (\n        <li key={i}>\n          <span className="t fig">{when(it.time)}</span>\n          <span className="what"><b>{it.label}</b>{it.change ? `: ${it.change}` : ""}</span>\n          <span className="why">{it.reason}</span>\n          <span className="by-line">{it.by}{it.role ? `, ${it.role}` : ""}</span>\n        </li>\n      ))}\n    </ol>\n  );\n}\n\nfunction Audit({ onEnded }) {\n  const [data, setData] = useState(null);\n  const [error, setError] = useState(null);\n  const [target, setTarget] = useState("");\n  const load = useCallback((t) => {\n    setError(null);\n    api(`/api/v1/ops-console/audit?limit=200${t ? `&target_id=${encodeURIComponent(t)}` : ""}`)\n      .then(setData).catch((e) => { if (!onEnded(e)) setError(e.message); });\n  }, [onEnded]);\n  useEffect(() => { load(""); }, [load]);\n  return (\n    <section className="audit">\n      <h1>Audit trail</h1>\n      <p className="quiet">Every action taken in this console, with who, when and why. Entries cannot be edited or removed.</p>\n      <form className="filter" onSubmit={(e) => { e.preventDefault(); load(target.trim()); }}>\n        <label>Client or user ID<input value={target} onChange={(e) => setTarget(e.target.value)} placeholder="All" /></label>\n        <button className="outline">Filter</button>\n      </form>\n      {error && <p className="msg bad">{error}</p>}\n      {data && (data.entries.length === 0\n        ? <p className="quiet">No entries.</p>\n        : (\n          <div className="scroll">\n            <table className="plain audit-table">\n              <thead><tr><th>Time (PKT)</th><th>Who</th><th>Action</th><th>Record</th><th>Reason</th><th>Status</th></tr></thead>\n              <tbody>\n                {data.entries.map((a, i) => (\n                  <tr key={i}>\n                    <td className="fig">{when(a.time).replace(" PKT", "")}</td>\n                    <td>{a.by}<span className="sub">{a.role}</span></td>\n                    <td>{ACTION[a.action] || a.action}</td>\n                    <td className="fig">{a.target_type} {a.target_id}</td>\n                    <td className="why">{a.reason}</td>\n                    <td>{a.before?.status && a.after?.status && a.before.status !== a.after.status\n                      ? `${STATUS[a.before.status] || a.before.status} to ${STATUS[a.after.status] || a.after.status}` : ""}</td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        ))}\n    </section>\n  );\n}\n', 'src/index.css': '/* Sentinel Operations: KSE Sentinel palette (as the Terminal), IBM Plex Sans.\n   Plex Mono only for figures: dates, amounts, IDs. */\n:root {\n  --navy: #1e2761; --navy-2: #283373; --gold: #b8860b; --gold-soft: #f3e3bf;\n  --slate: #44546a; --ink: #1b2035; --muted: #5e6b7e; --page: #f6f5f0;\n  --line: rgba(30, 39, 97, 0.16); --line-2: rgba(30, 39, 97, 0.28);\n  --good: #2f6f4f; --bad: #a33636; --bad-soft: #f6e4e4; --note: #fbf3e2;\n  font-family: "IBM Plex Sans", system-ui, sans-serif;\n  color: var(--ink); background: var(--page);\n  font-size: 14px; line-height: 1.5;\n}\n* { box-sizing: border-box; }\nbody { margin: 0; }\nbutton, input, select, textarea { font: inherit; color: inherit; }\nbutton { cursor: pointer; }\n:focus-visible { outline: 2px solid var(--gold); outline-offset: 2px; }\nh1 { font-size: 22px; font-weight: 600; color: var(--navy); margin: 0 0 18px; letter-spacing: -0.01em; }\nh2 { font-size: 17px; font-weight: 600; color: var(--navy); margin: 28px 0 10px; }\nh3 { font-size: 14px; font-weight: 600; color: var(--navy); margin: 26px 0 10px; }\n.fig { font-family: "IBM Plex Mono", monospace; font-variant-numeric: tabular-nums; font-size: 12.5px; }\n.quiet { color: var(--muted); }\n.boot { padding: 40px; color: var(--muted); }\n\n/* shell */\n.shell { display: grid; grid-template-columns: 232px 1fr; min-height: 100vh; background: linear-gradient(to right, var(--navy) 232px, var(--page) 232px); }\n.rail { background: var(--navy); color: #e8eaf4; display: flex; flex-direction: column; padding: 24px 0; position: sticky; top: 0; height: 100vh; }\n.brand { display: flex; flex-direction: column; padding: 0 22px 26px; }\n.brand-mark { color: var(--gold); font-weight: 600; font-size: 13px; letter-spacing: 0.04em; }\n.brand-name { font-size: 22px; font-weight: 600; color: #fff; letter-spacing: -0.01em; }\n.brand.dark .brand-name { color: var(--navy); }\n.rail nav { display: flex; flex-direction: column; }\n.rail nav button { text-align: left; background: none; border: 0; color: #c9cde3; padding: 10px 22px; border-left: 3px solid transparent; font-size: 14px; }\n.rail nav button:hover { color: #fff; background: var(--navy-2); }\n.rail nav button.on { color: #fff; border-left-color: var(--gold); background: var(--navy-2); font-weight: 600; }\n.who { margin-top: auto; padding: 16px 22px 0; border-top: 1px solid rgba(255,255,255,0.12); font-size: 12.5px; overflow-wrap: anywhere; }\n.who .role { color: #aab0cf; margin: 2px 0 8px; }\n.who .link { color: var(--gold-soft); padding: 0; }\n.work { padding: 30px 36px 60px; min-width: 0; }\n\n/* buttons */\n.primary, .danger, .outline, .danger-outline, .quietbtn { border-radius: 3px; padding: 8px 14px; font-weight: 600; font-size: 13px; }\n.primary { background: var(--navy); color: #fff; border: 1px solid var(--navy); }\n.danger { background: var(--bad); color: #fff; border: 1px solid var(--bad); }\n.outline { background: #fff; color: var(--navy); border: 1px solid var(--navy); }\n.danger-outline { background: #fff; color: var(--bad); border: 1px solid var(--bad); }\n.quietbtn { background: none; border: 1px dashed var(--line-2); color: var(--slate); margin-top: 16px; font-weight: 500; }\nbutton:disabled { opacity: 0.45; cursor: not-allowed; }\n.link { background: none; border: 0; color: var(--navy); text-decoration: underline; padding: 8px 4px; font-size: 13px; }\n\n/* sign in */\n.signin { min-height: 100vh; display: grid; place-items: center; padding: 24px; }\n.signin form { width: min(380px, 100%); display: flex; flex-direction: column; gap: 14px; border-top: 4px solid var(--gold); background: #fff; padding: 30px 30px 32px; border-left: 1px solid var(--line); border-right: 1px solid var(--line); border-bottom: 1px solid var(--line); }\n.signin .brand { padding: 0; }\n.lede { margin: 0 0 6px; color: var(--muted); }\nlabel { display: flex; flex-direction: column; gap: 5px; font-size: 12.5px; color: var(--slate); font-weight: 500; }\ninput, select, textarea { border: 1px solid var(--line-2); border-radius: 3px; padding: 8px 10px; background: #fff; font-size: 14px; color: var(--ink); }\ntextarea { resize: vertical; min-height: 58px; }\n.hint { font-size: 12px; color: var(--muted); font-weight: 400; }\n.msg { margin: 8px 0 0; padding: 9px 12px; background: var(--note); border-left: 3px solid var(--gold); font-size: 13px; }\n.msg.bad { background: var(--bad-soft); border-left-color: var(--bad); color: #6d2323; }\n.msg.good { background: #e6f1eb; border-left-color: var(--good); color: #1f4d36; }\n\n/* overview */\n.figures { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); border-top: 1px solid var(--line-2); border-bottom: 1px solid var(--line-2); }\n.figure { display: flex; flex-direction: column; align-items: flex-start; gap: 2px; padding: 18px 20px 18px 0; background: none; border: 0; text-align: left; }\n.figure + .figure { padding-left: 20px; border-left: 1px solid var(--line); }\nbutton.figure:hover .l { color: var(--navy); text-decoration: underline; }\n.figure .n { font-size: 34px; font-weight: 600; color: var(--navy); line-height: 1.1; font-variant-numeric: tabular-nums; }\n.figure .l { color: var(--muted); font-size: 13px; }\n\n/* tables */\ntable.plain { width: 100%; border-collapse: collapse; font-size: 13px; }\ntable.plain th { text-align: left; font-weight: 600; color: var(--slate); font-size: 12.5px; padding: 8px 10px; border-bottom: 1px solid var(--line-2); }\ntable.plain td { padding: 9px 10px; border-bottom: 1px solid var(--line); vertical-align: top; }\ntable.plain .sub { display: block; color: var(--muted); font-size: 12px; }\n.scroll { overflow-x: auto; }\n.audit-table .why { max-width: 380px; }\n.filter { display: flex; align-items: flex-end; gap: 10px; margin: 16px 0 18px; }\n\n/* onboarding: queue | record */\n.onboarding { display: grid; grid-template-columns: minmax(260px, 340px) minmax(0, 1fr); gap: 32px; align-items: start; }\n.tabs { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 12px; }\n.tabs button { background: none; border: 1px solid var(--line-2); border-radius: 14px; padding: 4px 11px; font-size: 12.5px; color: var(--slate); }\n.tabs button.on { background: var(--navy); border-color: var(--navy); color: #fff; }\n.rows { list-style: none; margin: 0; padding: 0; border-top: 1px solid var(--line); }\n.rows button { width: 100%; text-align: left; background: none; border: 0; border-bottom: 1px solid var(--line); border-left: 3px solid transparent; padding: 11px 12px; display: flex; flex-direction: column; gap: 1px; }\n.rows button:hover { background: #fff; }\n.rows button.on { background: #fff; border-left-color: var(--gold); }\n.rows .co { font-weight: 600; color: var(--ink); }\n.rows .sub { font-size: 12.5px; color: var(--muted); }\n.record { background: #fff; border: 1px solid var(--line); padding: 26px 30px 30px; min-height: 60vh; }\n.record .empty { margin: 0; }\n.rec-head { display: flex; justify-content: space-between; align-items: baseline; gap: 16px; flex-wrap: wrap; }\n.rec-head h2 { margin: 0; font-size: 20px; }\n.status { font-size: 12.5px; font-weight: 600; padding: 3px 10px; border-radius: 12px; background: #eceef6; color: var(--navy); white-space: nowrap; }\n.s-MORE_INFO_REQUESTED { background: var(--note); color: #6e4a0a; }\n.s-TRIAL_ACTIVE { background: #e6f1eb; color: var(--good); }\n.s-REJECTED, .s-TRIAL_EXPIRED, .s-SUSPENDED { background: var(--bad-soft); color: var(--bad); }\n.note { margin: 12px 0 0; padding: 9px 12px; background: var(--note); border-left: 3px solid var(--gold); font-size: 13px; }\n.facts { display: grid; grid-template-columns: repeat(auto-fill, minmax(210px, 1fr)); gap: 14px 24px; margin: 22px 0 0; }\n.fact dt { font-size: 12px; color: var(--muted); }\n.fact dd { margin: 2px 0 0; overflow-wrap: anywhere; }\n.block { border-top: 1px solid var(--line); margin-top: 24px; }\n\n/* checklist */\n.checks { display: flex; flex-direction: column; }\n.check { display: grid; grid-template-columns: minmax(0, 1fr) auto minmax(150px, 220px); gap: 6px 14px; align-items: center; padding: 9px 0; border-bottom: 1px solid var(--line); }\n.check .q { font-size: 13.5px; }\n.check .by { grid-column: 1 / -1; font-size: 11.5px; color: var(--muted); }\n.answers { display: flex; }\n.answers button { background: #fff; border: 1px solid var(--line-2); padding: 4px 10px; font-size: 12.5px; color: var(--slate); }\n.answers button + button { border-left: 0; }\n.answers button:first-child { border-radius: 3px 0 0 3px; }\n.answers button:last-child { border-radius: 0 3px 3px 0; }\n.answers button.on.a-yes { background: var(--good); border-color: var(--good); color: #fff; }\n.answers button.on.a-no { background: var(--bad); border-color: var(--bad); color: #fff; }\n.answers button.on.a-na { background: var(--slate); border-color: var(--slate); color: #fff; }\n.note-in { font-size: 13px; padding: 5px 8px; }\n\n/* forms and decisions */\n.form-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 12px 18px; margin-bottom: 14px; }\nfieldset.pilot { border: 1px solid var(--line-2); border-radius: 3px; padding: 6px 12px 10px; display: flex; flex-direction: column; gap: 6px; margin: 0; }\nfieldset.pilot legend { font-size: 12.5px; color: var(--slate); font-weight: 500; padding: 0 4px; }\nfieldset.pilot label { flex-direction: row; align-items: center; gap: 8px; font-size: 13.5px; color: var(--ink); font-weight: 400; }\nlabel.inline { flex-direction: row; align-items: center; flex-wrap: wrap; gap: 8px; font-size: 13.5px; color: var(--ink); margin-bottom: 12px; }\nlabel.inline input { width: 80px; }\n.choices { display: flex; flex-wrap: wrap; gap: 10px; }\n.reasoned { border-left: 3px solid var(--navy); background: #f9f9fb; padding: 12px 14px 14px; display: flex; flex-direction: column; gap: 8px; }\n.reasoned.danger { border-left-color: var(--bad); background: #fcf6f6; }\n.reasoned .row { display: flex; align-items: center; gap: 8px; }\n.confirm { margin: 0; font-weight: 600; color: var(--bad); font-size: 13px; }\n\n/* timeline: a genuine sequence of events */\n.timeline { list-style: none; margin: 0; padding: 0; }\n.timeline li { display: grid; grid-template-columns: 170px minmax(0, 1fr); gap: 2px 16px; padding: 10px 0; border-bottom: 1px solid var(--line); }\n.timeline .t { grid-row: span 3; color: var(--muted); padding-top: 2px; }\n.timeline .what b { font-weight: 600; color: var(--ink); }\n.timeline .why { color: var(--slate); font-size: 13px; }\n.timeline .by-line { color: var(--muted); font-size: 12px; }\n\n@media (max-width: 1000px) {\n  .shell { grid-template-columns: 1fr; background: var(--page); }\n  .rail { position: static; height: auto; flex-direction: row; flex-wrap: wrap; align-items: center; padding: 12px 16px; gap: 12px; }\n  .rail .brand { padding: 0; }\n  .rail nav { flex-direction: row; flex-wrap: wrap; }\n  .rail nav button { border-left: 0; border-bottom: 3px solid transparent; padding: 8px 12px; }\n  .rail nav button.on { border-bottom-color: var(--gold); }\n  .who { margin: 0 0 0 auto; border: 0; padding: 0; }\n  .work { padding: 20px 16px 40px; }\n  .onboarding { grid-template-columns: 1fr; }\n  .figures { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .figure:nth-child(3) { padding-left: 0; border-left: 0; }\n  .check { grid-template-columns: 1fr; }\n  .timeline li { grid-template-columns: 1fr; }\n  .timeline .t { grid-row: auto; }\n}\n@media (prefers-reduced-motion: reduce) { * { transition: none !important; animation: none !important; } }\n', 'README.md': "# Sentinel Operations\n\nInternal console for the MZE Digital team (KSE Sentinel). Private.\nSpec: KSE_Sentinel_Operations_Console_Spec.md (v3).\n\nRuns locally only until team MFA (Phase 0b) is in place; it is then deployed\nto ops.kse-sentinel.com.\n\n    npm install\n    npm run dev          # http://localhost:5174\n\nSettings (.env, never committed):\n\n    VITE_API_BASE=http://localhost:8001\n    VITE_API_KEY=<the platform API key, as in the Terminal's .env>\n\nThe backend must list http://localhost:5174 in ALLOWED_ORIGINS.\n"}
REMOVE = ["src/App.css", "src/assets/react.svg", "public/vite.svg"]


def main():
    pkg = Path("package.json")
    if not pkg.exists() or '"react"' not in pkg.read_text(encoding="utf-8"):
        sys.exit("No React project here. Run this in kse-sentinel-ops after: npm create vite@latest . -- --template react")
    for name, content in FILES.items():
        p = Path(name)
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(content, encoding="utf-8")
        print(f"Wrote {name}")
    for name in REMOVE:
        if Path(name).exists():
            Path(name).unlink()
            print(f"Removed starter file {name}")

    gi = Path(".gitignore")
    lines = gi.read_text(encoding="utf-8").splitlines() if gi.exists() else []
    if ".env" not in [l.strip() for l in lines]:
        gi.write_text("\n".join(lines + ["", "# settings and API key: never commit", ".env"]) + "\n", encoding="utf-8")
        print("Added .env to .gitignore")

    env = Path(".env")
    if env.exists():
        print(".env already exists: left unchanged")
    else:
        key_line = None
        terminal_env = Path("..") / "kse-sentinel-terminal" / ".env"
        if terminal_env.exists():
            for line in terminal_env.read_text(encoding="utf-8").splitlines():
                if line.strip().startswith("VITE_API_KEY="):
                    key_line = line.strip()
        env.write_text("VITE_API_BASE=http://localhost:8001\n" + (key_line or "VITE_API_KEY=") + "\n", encoding="utf-8")
        print("Created .env" + (" (API key copied from the Terminal's .env)" if key_line else
                                 " WITHOUT an API key: add the VITE_API_KEY line from the Terminal's .env by hand"))
    print("\nDone. Next: npm run dev, then open http://localhost:5174")


if __name__ == "__main__":
    main()